23:   --leading-tight:   1;      /* 36px+ headlines */
24:   --leading-snug:    1.25;   /* 20-30px */
25:   --leading-normal:  1.5;    /* body, narrow measure */
26:   --leading-loose:   1.75;   /* small text, or wide measure */
27:   --measure: 34em;           /* 45-75 chars */
