29:   /* ---- Greys (cool). Almost all of a UI is grey.
30:          Ratios below are vs --grey-100; on pure white each is ~10% higher. ---- */
31:   --grey-100: hsl(210, 36%, 96%);   /* page background */
32:   --grey-200: hsl(212, 33%, 89%);   /* borders, dividers */
33:   --grey-300: hsl(211, 27%, 84%);
