39:   --grey-600: hsl(209, 28%, 39%);   /*  5.6:1 — tertiary text (footnotes, copyright) */
40:   --grey-700: hsl(209, 34%, 30%);   /*  8.0:1 — secondary text */
41:   --grey-800: hsl(211, 39%, 23%);   /* 10.7:1 */
42:   --grey-900: hsl(209, 61%, 16%);   /* 13.4:1 — primary text */
43: 
44:   /* ---- Primary. 500 is the shade that works as a button background. ---- */
45:   --primary-100: hsl(205, 92%, 92%);  /* tinted background */
46:   --primary-200: hsl(205, 97%, 85%);
47:   --primary-300: hsl(205, 90%, 76%);
48:   --primary-400: hsl(206, 82%, 58%);
49:   --primary-500: hsl(208, 88%, 38%);  /* base — white text passes AA */
50:   --primary-600: hsl(209, 88%, 33%);
51:   --primary-700: hsl(211, 88%, 28%);
52:   --primary-800: hsl(213, 88%, 23%);
53:   --primary-900: hsl(215, 88%, 18%);  /* text on --primary-100 */
54: 
