62:   --yellow-500:hsl( 42, 100%, 29%);
63:   --yellow-800:hsl( 38, 100%, 19%);
64: 
65:   --green-100: hsl(152,  68%, 92%);
66:   --green-500: hsl(154,  85%, 24%);
67:   --green-800: hsl(156, 100%, 13%);
68: 
69:   /* ---- Elevation. Pick by z-position, not by looks. ---- */
70:   --shadow-1: 0 1px 3px   hsla(0, 0%, 0%, .2);   /* buttons */
71:   --shadow-2: 0 4px 6px   hsla(0, 0%, 0%, .2);   /* dropdowns */
72:   --shadow-3: 0 5px 15px  hsla(0, 0%, 0%, .2);
