77:   --radius:      4px;   /* neutral. 0 = formal, 12px+ = playful */
78:   --radius-full: 9999px;
79: 
80:   /* ---- Border width: fixed, like everything else ---- */
81:   --border-width:       1px;
82:   --border-width-thick: 2px;  /* when a soft-colored 1px border reads too subtle */
83: 
84:   /* ---- Opacity: fixed set, not a slider you eyeball each time ---- */
85:   --opacity-1: .05;   /* hairline overlays */
86:   --opacity-2: .1;    /* subtle tints, inset shadows on images */
87:   --opacity-3: .2;    /* disabled controls */
88:   --opacity-4: .4;    /* scrims under light text */
89:   --opacity-5: .6;    /* dark overlay on photos */
90:   --opacity-6: .8;    /* near-opaque overlay */
91: 
92:   /* ---- Semantic roles. Reference these in components, not the raw ramps —
93:          it's the only way the dark-mode block below can work. ---- */
94:   --surface:         var(--grey-100);  /* page */
95:   --surface-raised:  #fff;             /* cards — lighter than the page */
96:   --surface-sunken:  var(--grey-200);  /* wells, inset areas */
97:   --border:          var(--grey-300);  /* DECORATIVE dividers only (1.3:1). Distinct from
98:                                           --surface-sunken on purpose: a bordered input
99:                                           inside a well needs a visible edge. */
100:   --border-strong:   var(--grey-500);  /* FUNCTIONAL borders — input outlines, checkbox
101:                                           edges, focus rings. Anything that is the only
102:                                           thing identifying a control needs 3:1 per WCAG
103:                                           1.4.11. 3.9 on surface / 4.3 on raised / 3.3 in
104:                                           a sunken well. */
105:   --text-primary:    var(--grey-900);
106:   --text-secondary:  var(--grey-700);
107:   --text-tertiary:   var(--grey-600);
108:   --text-disabled:   var(--grey-400);
109:   --action:          var(--primary-500);
110:   --action-text:     #fff;
111: }
112: 
113: /* Dark mode. Not a mechanical inversion — surfaces stack *upward* in lightness,
114:    accents move to the light end of the ramp, and text sits a shade dimmer than
115:    the light-mode equivalent. All *text* pairs verified >= 4.5:1; functional borders
116:    are held to the 3:1 non-text bar instead (WCAG 1.4.11); decorative dividers and
117:    disabled text are exempt from both. */
118: @media (prefers-color-scheme: dark) {
119:   :root {
120:     --surface:        var(--grey-900);   /* never pure black */
121:     --surface-raised: var(--grey-800);   /* raised = lighter, same as light mode. Only a
122:                                             1.26:1 step, and shadows barely register here —
123:                                             so give raised surfaces a --border-strong
124:                                             hairline. Going lighter instead (grey-700) would
125:                                             break --text-tertiary, which drops to 3.6:1. */
126:     --surface-sunken: hsl(209, 61%, 12%);
127:     --border:         var(--grey-700);   /* decorative only (1.7:1) */
128:     --border-strong:  var(--grey-400);   /* functional, 3:1+. Note this goes *lighter* while
129:                                             light mode goes darker — the mirror image
130:                                             (grey-500) fails at 2.7:1 on a raised surface. */
131:     --text-primary:   var(--grey-200);   /* 11.3:1 — grey-100 is too harsh here */
132:     --text-secondary: var(--grey-300);   /*  10.0:1 */
133:     --text-tertiary:  hsl(209, 23%, 66%);/*  6.1:1 base / 4.8:1 raised — sits between
134:                                             grey-400 and grey-300, because grey-400 fails
135:                                             (4.0:1) against a raised surface */
136:     --text-disabled:  var(--grey-600);   /* 2.4:1 — near light mode's 2.7:1. grey-500
137:                                             (3.4:1) reads *more* legible than light mode,
138:                                             which is backwards for a disabled affordance. */
139:     --action:         var(--primary-400);/* light fill + dark text, 5.2:1 */
140:     --action-text:    var(--grey-900);
141: 
142:     /* Shadows do little work on dark surfaces — lightness carries depth instead. */
143:     --shadow-1: 0 1px 3px   hsla(0, 0%, 0%, .4);
144:     --shadow-2: 0 4px 6px   hsla(0, 0%, 0%, .4);
145:     --shadow-3: 0 5px 15px  hsla(0, 0%, 0%, .45);
146:     --shadow-4: 0 10px 24px hsla(0, 0%, 0%, .5);
147:     --shadow-5: 0 15px 35px hsla(0, 0%, 0%, .55);
148:   }
149: }

